import{B as e,F as t,I as n,L as r,M as i,R as a,Z as o,wt as s}from"./chunks/framework.BLmRAsdY.js";import{n as c,t as l}from"./chunks/Canvas.C_CUnsxH.js";var u=JSON.parse(`{"title":"Client-Side Encryption v2.1","description":"","frontmatter":{},"headers":[],"relativePath":"deep-dive/modules/encryption.md","filePath":"en/deep-dive/modules/encryption.md","lastUpdated":1795199667000}`),d=e({name:`deep-dive/modules/encryption.md`,setup(e){return(e,u)=>(o(),t(`div`,null,[u[0]||=i(`h1`,{id:`client-side-encryption-v2-1`,tabindex:`-1`},[r(`Client-Side Encryption v2.1 `),i(`a`,{class:`header-anchor`,href:`#client-side-encryption-v2-1`,"aria-label":`Permalink to “Client-Side Encryption v2.1”`},`​`)],-1),u[1]||=i(`p`,null,[r(`The plugin uploads encrypted files to remote, download and decrypt back to local. This document specifies the encryption algorithm implementation in the `),i(`code`,null,`Encryption`),r(` module.`)],-1),u[2]||=i(`p`,null,`Encryption implementation in this module welcomes volunteer auditing.`,-1),a(l,{canvas:s(c)},null,8,[`canvas`]),u[3]||=n(`<h2 id="terminology" tabindex="-1">Terminology <a class="header-anchor" href="#terminology" aria-label="Permalink to “Terminology”">​</a></h2><h3 id="notations" tabindex="-1">Notations <a class="header-anchor" href="#notations" aria-label="Permalink to “Notations”">​</a></h3><ul><li>IV = Initialization Vector = Nonce</li><li>B = Byte</li><li>b = bit</li><li>1KiB = 1024B</li><li>|| = concatenate</li></ul><h3 id="threat-model-constraints" tabindex="-1">Threat Model &amp; Constraints <a class="header-anchor" href="#threat-model-constraints" aria-label="Permalink to “Threat Model &amp; Constraints”">​</a></h3><p><strong>The implementation trusts</strong>:</p><ul><li>Clients share password outside of the module. And the share channel is out of scope so the module doesn&#39;t need to implement its own key exchange.</li><li>The operating system or Obsidian runtime are not compromised.</li></ul><p><strong>The implementation does not trust</strong>:</p><ul><li>Backend server</li><li>Transmission layer</li></ul><p><strong>The implementation protects against</strong>:</p><ul><li>Unauthorized access</li><li>Unauthorized modification or file truncation</li><li>Encryption combined with <a href="./../asymmetric-storage">Asymmetric Storage</a> can yield better obfuscation since it flattens hierarchical structure and randomizes file basenames.</li></ul><p><strong>The implementation cannot</strong>:</p><ul><li>Prevent file rollback to a previous version</li><li>Prevent unintended renaming or movement</li><li>Prevent deletion at server side</li><li>Obfuscate file size or modification time</li><li>Obfuscate total file count</li><li>Obfuscate remote root directory name</li><li>Obfuscate keys in the server&#39;s key-value file metadata storage</li></ul><h3 id="algorithms" tabindex="-1">Algorithms <a class="header-anchor" href="#algorithms" aria-label="Permalink to “Algorithms”">​</a></h3><ul><li><code>SHA256</code>: generate deterministic and unique salt from user info to obtain <em>master key</em>.</li><li><code>Argon2id</code>: generate <em>master key</em> from salt and user password, used every user info / password change.</li><li><code>HKDF-SHA-256</code>: derive <em>root file key</em>, <em>name key</em>, and <em>meta key</em> from <em>master key</em>, and derive <em>file key</em> from <em>root file key</em> and <em>file salt</em>, used every sync.</li><li><code>CSPRNG</code>: (<code>crypto.getRandomValues()</code>) generate random <em>file salt</em>, used every file encryption</li><li><code>AES-GCM-256</code>: main algorithm used to encrypt file content and meta values, used every file encryption</li><li><code>AES-GCM-SIV-256</code>: algorithm used to encrypt file / folder names, used every file encryption</li><li><code>Base64URL</code>: transform binary data into ASCII for file name storage</li><li><code>Base64</code>: transform binary data into ASCII for meta value storage</li></ul><h3 id="keys-data-structure" tabindex="-1">Keys &amp; data structure <a class="header-anchor" href="#keys-data-structure" aria-label="Permalink to “Keys &amp; data structure”">​</a></h3><ul><li><em>user password</em>: the raw string user password</li><li><em>auth tag</em>: 16B, generated by <code>AES-GCM-256</code> to verify data integrity</li><li><em>master salt</em>: 16B, for salting <em>user password</em> to get <em>master key</em>, generated from <code>SHA256</code> on user info</li><li><em>master key</em>: 32B, deterministic strong key generated by <code>Argon2id</code> from <em>user password</em> and <em>master salt</em></li><li><em>name key</em>: 32B, derived from <em>master key</em> used to encrypt file names</li><li><em>root file key</em>: 32B, derived from <em>master key</em> used to generate <em>file key</em> for each file</li><li><em>meta key</em>: 32B, derived from <em>master key</em> used to encrypt meta values</li><li><em>file key</em>: 32B, derived from <em>root file key</em> and random <em>file salt</em></li><li><em>file salt</em>: 16B, pure random, to derive <em>file key</em> each time to encrypt or decrypt a file</li><li><em>file key salt</em>: 32B, <code>SHA256</code> of <em>file salt</em> || encrypted file size in 8B</li><li><em>chunk nonce</em>: 12B, chunk index represented in 12B.</li><li><em>encrypted file / folder name</em>: <code>Base64URL</code> of <code>AES-GCM-SIV</code> encrypted file name</li><li><em>encrypted file / folder path</em>: <em>encrypted file / folder name</em> of all ancestor hierarchies joint by <code>/</code>.</li><li><em>file chunk</em>: 131,088B, 128KiB-chunked and <code>AES-GCM-256</code> encrypted piece of file (end chunk can be smaller)</li><li><em>encrypted file content</em>: <em>file salt</em> || all chunks sequentially</li><li><em>meta nonce</em>: 12B, pure random, generated per meta value encryption via <code>CSPRNG</code></li><li><em>encrypted meta value</em>: <code>Base64</code> of <em>meta nonce</em> || <code>AES-GCM-256</code> ciphertext (including 16B auth tag)</li></ul><h2 id="enabling-and-disabling" tabindex="-1">Enabling and Disabling <a class="header-anchor" href="#enabling-and-disabling" aria-label="Permalink to “Enabling and Disabling”">​</a></h2><p>The function is toggled via the <strong>Encryption</strong> setting. The password is stored in Obsidian&#39;s keychain. When a record store exists, changing the toggle opens a confirmation prompt, similar to <a href="./../../usage/settings#asymmetric-storage">asymmetric storage</a>; confirm only after your remote data has been migrated as described in the <a href="./../../usage/remote-migration">Remote Migration guide</a>.</p><h2 id="sync-routine" tabindex="-1">Sync Routine <a class="header-anchor" href="#sync-routine" aria-label="Permalink to “Sync Routine”">​</a></h2><p>On each sync, generate a promise to obtain <em>root file key</em>, <em>name key</em>, and <em>meta key</em> that will be resolved and cached on demand:</p><ul><li>starting check: if found the user password is an empty string or undefined, throw directly</li><li>generate <em>master salt</em>: <code>SHA256</code> of <strong>distinguishing data of the configured backend account that is often safe to disclose (like account name + server URL + directory prefix)</strong> truncated to 16B.</li><li>generate <em>master key</em> using <code>Argon2id</code> with 32MB memory, 3 iterations, and 1 thread on the <em>user password</em> with <em>master salt</em></li><li>derive <em>root file key</em> (info: <code>root-file-key-v1</code>, no salt), <em>name key</em> (info: <code>name-key-v1</code>, no salt), and <em>meta key</em> (info: <code>meta-key-v1</code>, no salt) using <code>HKDF-SHA-256</code></li><li>resolve with <em>root file key</em>, <em>name key</em>, and <em>meta key</em></li></ul><p>Then come to the traversal and syncing logic:</p><ul><li>encryption and decryption are isolated in a remote <a href="./../file-system-wrappers">filesystem wrapper</a>. The wrapper transparently transforms keys and contents of every file system operation.</li><li>assume all files are encrypted when &quot;Encryption&quot; is enabled, assume all plain when not enabled.</li></ul><h2 id="file-folder-path-encryption" tabindex="-1">File / Folder Path Encryption <a class="header-anchor" href="#file-folder-path-encryption" aria-label="Permalink to “File / Folder Path Encryption”">​</a></h2><ul><li>All paths should be represented in UTF-8 and normalized to Unicode NFC</li><li>Cascade and encrypt the whole path chain, for each file name (should be a standalone name like <code>bar</code>, <code>foo.md</code>): <ul><li>use <code>AES-GCM-SIV-256</code> to encrypt file name with key: <em>name key</em>, content: file name, nonce: fixed at UTF-8 of <code>file-name-v1</code> in bytes.</li><li>obtain the final name using <code>Base64URL</code> on the result yielded above</li></ul></li><li>For example, when encrypting the full path of <code>foo/bar/a.md</code>, first encrypt <code>foo</code>, then <code>bar</code> folder, and finally <code>a.md</code>.</li><li>Use a global in-memory cache to accelerate file path encryption / decryption for identical paths, limited to 10K entries.</li><li>Do not encrypt user&#39;s remote root directory.</li></ul><h2 id="file-encryption" tabindex="-1">File Encryption <a class="header-anchor" href="#file-encryption" aria-label="Permalink to “File Encryption”">​</a></h2><ul><li>Input raw file and raw file size</li><li>Generate random 16B <em>file salt</em> via <code>CSPRNG</code></li><li>Calculate encrypted file size as <code>raw size + 16B + ceil(raw size / 128KiB) * 16B</code></li><li>Calculate <em>file key salt</em> as <code>SHA256</code> of <em>file salt</em> || encrypted file size in 8B</li><li>Calculate <em>file key</em> using <code>HKDF-SHA-256</code> of <em>root file key</em> (salt: <em>file key salt</em>, info: <code>file-key-v1</code>).</li><li>Splice the file content into 128KiB chunks, special size for the last chunk, for each chunk: <ul><li>get chunk index starting from 0 represented in 12B as <em>chunk nonce</em></li><li>encrypt the 128KiB with <em>file key</em> and <em>chunk nonce</em> using <code>AES-GCM-256</code></li><li>each chunk = ciphertext (128KiB = 131,072B) + auth tag (16B) = 131,088B</li></ul></li><li>Concatenate the file as: <em>file salt</em> || all chunks sequentially</li></ul><h2 id="metadata-encryption" tabindex="-1">Metadata Encryption <a class="header-anchor" href="#metadata-encryption" aria-label="Permalink to “Metadata Encryption”">​</a></h2><ul><li>Derive <em>meta key</em> from <em>master key</em> using <code>HKDF-SHA-256</code> (info: <code>meta-key-v1</code>, no salt)</li><li>For each non-empty meta value: <ul><li>Generate random 12B <em>meta nonce</em> via <code>CSPRNG</code></li><li>Encrypt the UTF-8 encoded value with <em>meta key</em> and <em>meta nonce</em> using <code>AES-GCM-256</code></li><li>Encode as <code>Base64</code> of <em>meta nonce</em> || ciphertext (including 16B auth tag)</li></ul></li><li>Decryption reverses the process: <code>Base64</code> decode, split <em>meta nonce</em> (first 12B) and ciphertext, decrypt with <code>AES-GCM-256</code></li></ul><h2 id="one-pass-decryption" tabindex="-1">One-pass Decryption <a class="header-anchor" href="#one-pass-decryption" aria-label="Permalink to “One-pass Decryption”">​</a></h2><ul><li>Input encrypted file and encrypted size in bytes</li><li>Splice the first 16B as <em>file salt</em></li><li>Calculate <em>file key salt</em> as <code>SHA256</code> of <em>file salt</em> || encrypted file size in 8B</li><li>Calculate <em>file key</em> using <code>HKDF-SHA-256</code> of <em>root file key</em> (salt: <em>file key salt</em>, info: <code>file-key-v1</code>).</li><li>Continue to splice into 131,088B pieces (exception for the last chunk), for each piece: <ul><li>count <em>chunk index</em> as <em>chunk nonce</em></li><li>decrypt the chunk with <em>chunk nonce</em> + <em>file key</em> with <code>AES-GCM-256</code>, throw <code>Decryption error: incorrect encryption password or the data is corrupted</code> and skip the file if auth tag mismatch</li></ul></li><li>Concatenate decrypted content</li></ul><h2 id="streamed-decryption" tabindex="-1">Streamed Decryption <a class="header-anchor" href="#streamed-decryption" aria-label="Permalink to “Streamed Decryption”">​</a></h2><p>Streamed decryption receives a <code>ReadableStream</code>, generates another <code>ReadableStream</code>, and pipe decrypts it between streams.</p><ul><li>Input the encrypted size in bytes, and accept a sequential binary stream of the file content</li><li>Split and concatenate the chunk internally</li><li>For example, if the first received binary is 2,000,000B in size, the range decrypter: <ul><li>strips first 16B as <em>file salt</em></li><li>add up counter for each chunk and strip next 1966380B as 15 <em>completed chunks</em></li><li>save the last 33604B as an <em>incomplete chunk</em> and save to a buffer</li><li>decrypt the 15 <em>completed chunks</em> like one-pass decryption</li><li>concatenate content, and pipe to new stream.</li><li>when next binary stream chunk arrives, it concatenates the content in the buffer with the first certain size of bytes in the new binary as the first <em>completed chunk</em>.</li><li>repeat until the original stream finishes, the class treats the rest content in its buffer as a <em>completed chunk</em>, decrypt directly, pipe to the new stream, then end it.</li></ul></li></ul><h2 id="streamed-encryption" tabindex="-1">Streamed Encryption <a class="header-anchor" href="#streamed-encryption" aria-label="Permalink to “Streamed Encryption”">​</a></h2><p>Streamed encryption follows symmetrical path with streamed decryption.</p><ul><li>Input the unencrypted size in bytes and a <code>ReadableStream</code> of file content.</li><li>Calculate the encrypted size as <code>raw size + 16B + ceil(raw size / 128KiB) * 16B</code></li><li>Calculate <em>file key salt</em> as <code>SHA256</code> of <em>file salt</em> || encrypted file size in 8B</li><li>Calculate <em>file key</em> using <code>HKDF-SHA-256</code> of <em>root file key</em> (salt: <em>file key salt</em>, info: <code>file-key-v1</code> constant string).</li><li>Creates a <code>TransformStream</code> above the original stream.</li><li>Constantly reads the stream, encrypts and maintains a buffer of raw bytes: if the buffer &lt; 128KiB after reserving a stream chunk, continue reading; if larger than 128KiB, encrypt the max number of 128KiB chunks in the buffer and emit. When stream ends, encrypt and emit the rest in the buffer.</li><li>The first emitted should have <em>file salt</em> prepended.</li></ul><h2 id="file-folder-name-decryption" tabindex="-1">File / Folder Name Decryption <a class="header-anchor" href="#file-folder-name-decryption" aria-label="Permalink to “File / Folder Name Decryption”">​</a></h2><ul><li>Input file name and <code>Base64URL</code> decode to raw bytes</li><li>Decrypt the rest of the file name using <code>AES-GCM-SIV-256</code> with <em>name key</em> and nonce (use the cache if possible)</li></ul><h2 id="implementation" tabindex="-1">Implementation <a class="header-anchor" href="#implementation" aria-label="Permalink to “Implementation”">​</a></h2><p>The implementation should only use:</p><ul><li>Web Crypto</li><li><code>argon2id</code> export from <code>hash-wasm</code></li><li><code>gcmsiv</code> export from <code>@noble/ciphers/aes.js</code></li></ul><p>The encryption function will be cleanly integrated inside the <code>encryption</code> package as a Sync Engine optional module, which ships a <a href="./../file-system-wrappers"><code>RemoteFsWrapper</code></a>:</p><p>Receives the memory database instance and <em>user password</em> in the second argument.</p><p><code>getUid()</code>, <code>checkConnection()</code>, <code>options</code>: keep as-is.</p><p><code>read()</code>: encrypt key before relaying to original, and decrypt when original returns.</p><p><code>readStream()</code>: encrypt key before relaying to original, creates a new <code>transformStream</code> that relays the original stream.</p><p><code>write()</code>: encrypt the key, content, and meta values before relaying to original.</p><p><code>writeStream()</code>: encrypt the key, meta values, and stream content before relaying to original.</p><p><code>delete()</code>, <code>mkdir()</code>: encrypt the key before relaying to original.</p><p><code>stat()</code>: encrypt the key before relaying, decrypt the <code>key</code> and meta values in <code>Stat</code> when original returns.</p><p><code>list()</code>: encrypt the key before relaying, decrypt the <code>key</code> and meta values in <code>Array&lt;Stat&gt;</code> when original returns.</p><p>Path segments and derived keys are cached, persistent beyond sync runs. The cache is based on Uni-KV <code>memoryDB</code> obtained from context, similar to <a href="./../file-system-wrappers">Context Wrapper</a>, the cache is reset only when signals changed:</p><ul><li>Store meta: <code>EncryptionDBMeta</code></li><li>Storage schema: <code>EncryptionDBSchema</code></li><li>Scope: <code>decryptedToEncrypted</code> and <code>encryptedToDecrypted</code> stores</li></ul><p>Behavior:</p><ul><li><code>memoryDB</code> from context is of different type, cast it to <code>MemoryDatabase&lt;EncryptionDBSchema, EncryptionDBMeta&gt;</code>.</li><li><code>encryptionMarker</code> = <code>RemoteFs.getUid()</code> || <code>~</code> || <em>user password</em></li><li>Cached derived keys are stored in store meta <code>encryptionKeys</code> field</li><li>Only once when the wrapper is activated: check if store meta <code>encryptionMarker</code> is aligned with the current one. If not, clear stores and <code>encryptionKeys</code>, and update the meta to the current uid.</li></ul>`,56)]))}});export{u as __pageData,d as default};